resource "azurerm_monitor_autoscale_setting" "batch_nonprod" {
  target_resource_id = azurerm_linux_virtual_machine_scale_set.batch_nonprod.id

  profile {
    name = "weekday-hours"
    capacity { minimum = 8, maximum = 8, default = 8 }
    recurrence {
      timezone = "Eastern Standard Time"
      days     = ["Monday","Tuesday","Wednesday","Thursday","Friday"]
      hours    = [7]
      minutes  = [0]
    }
  }

  profile {
    name = "off-hours"
    capacity { minimum = 0, maximum = 0, default = 0 }
    recurrence {
      timezone = "Eastern Standard Time"
      days     = ["Monday","Tuesday","Wednesday","Thursday","Friday"]
      hours    = [19]
      minutes  = [0]
    }
  }
}

